css:
/* Dashboard — replaces the desktop via the `desktop` slot (clean base). */
.shell .dash { box-sizing: border-box; display: grid; grid-template-rows: auto 1fr; gap: 22px; height: 100%; overflow: auto; padding: 64px 40px 96px; }
.shell .dash__head { display: flex; align-items: baseline; justify-content: space-between; }
.shell .dash__head h1 { margin: 0; font-size: 26px; font-weight: 700; letter-spacing: -0.02em; }
.shell .dash__clock { font-size: 22px; font-variant-numeric: tabular-nums; font-weight: 700; color: #4f46e5; }
.shell .dash__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 18px; align-content: start; }
.shell .dash__panel { border: 1px solid #d7dce6; border-radius: 18px; background: #ffffff; padding: 18px; box-shadow: 0 2px 10px rgba(17, 24, 39, 0.06); }
.shell .dash__panel h2 { margin: 0 0 12px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.12em; color: #6b7280; }
.shell .dash__apps { display: grid; grid-template-columns: repeat(auto-fill, minmax(72px, 1fr)); gap: 12px; }
.shell .dash__app { display: grid; justify-items: center; gap: 6px; border: 0; background: transparent; color: inherit; cursor: pointer; padding: 6px; border-radius: 12px; font: inherit; }
.shell .dash__app:hover { background: #eef1f6; }
.shell .dash__app-icon { width: 44px; height: 44px; }
.shell .dash__win, .shell .dash__action { display: block; width: 100%; text-align: left; border: 1px solid #d7dce6; background: #f7f9fc; border-radius: 10px; padding: 10px 12px; margin-bottom: 8px; font: inherit; color: inherit; cursor: pointer; }
.shell .dash__win:hover, .shell .dash__action:hover { border-color: #4f46e5; }
.shell :focus-visible { outline: 2px solid #4f46e5 !important; outline-offset: 2px; }
